package broll

import (
	"errors"
	"fmt"
)

type Kind int

const (
	KindMalformed Kind = iota
	KindIncomplete
	KindChecksum
	KindIntegerOverflow
	KindDecompressionBomb
	KindDecompressionCorrupt
	KindFrameTooLarge
	KindBufferBudget
	KindCPUBudget
	KindDepthExceeded
)

var (
	ErrMalformed            = errors.New("malformed frame")
	ErrIncomplete           = errors.New("incomplete frame")
	ErrChecksumMismatch     = errors.New("checksum mismatch")
	ErrIntegerOverflow      = errors.New("integer overflow")
	ErrDecompressionBomb    = errors.New("decompression bomb")
	ErrDecompressionCorrupt = errors.New("decompression corrupt")
	ErrFrameTooLarge        = errors.New("frame too large")
	ErrBufferBudget         = errors.New("buffer budget exceeded")
	ErrCPUBudget            = errors.New("cpu budget exceeded")
	ErrDepthExceeded        = errors.New("nesting depth exceeded")
)

func (k Kind) sentinel() error {
	switch k {
	case KindMalformed:
		return ErrMalformed
	case KindIncomplete:
		return ErrIncomplete
	case KindChecksum:
		return ErrChecksumMismatch
	case KindIntegerOverflow:
		return ErrIntegerOverflow
	case KindDecompressionBomb:
		return ErrDecompressionBomb
	case KindDecompressionCorrupt:
		return ErrDecompressionCorrupt
	case KindFrameTooLarge:
		return ErrFrameTooLarge
	case KindBufferBudget:
		return ErrBufferBudget
	case KindCPUBudget:
		return ErrCPUBudget
	case KindDepthExceeded:
		return ErrDepthExceeded
	}
	return ErrMalformed
}

func (k Kind) String() string {
	switch k {
	case KindMalformed:
		return "malformed"
	case KindIncomplete:
		return "incomplete"
	case KindChecksum:
		return "checksum"
	case KindIntegerOverflow:
		return "integer-overflow"
	case KindDecompressionBomb:
		return "decompression-bomb"
	case KindDecompressionCorrupt:
		return "decompression-corrupt"
	case KindFrameTooLarge:
		return "frame-too-large"
	case KindBufferBudget:
		return "buffer-budget"
	case KindCPUBudget:
		return "cpu-budget"
	case KindDepthExceeded:
		return "depth-exceeded"
	}
	return "unknown"
}

type ParseError struct {
	Kind   Kind
	Offset int64
	Detail string
}

func (e *ParseError) Error() string {
	if e.Detail == "" {
		return fmt.Sprintf("broll: %s frame at offset %d", e.Kind, e.Offset)
	}
	return fmt.Sprintf("broll: %s frame at offset %d: %s", e.Kind, e.Offset, e.Detail)
}

func (e *ParseError) Is(target error) bool { return target == e.Kind.sentinel() }
func (e *ParseError) Unwrap() error         { return e.Kind.sentinel() }

func perr(k Kind, off int64, format string, args ...any) *ParseError {
	return &ParseError{Kind: k, Offset: off, Detail: fmt.Sprintf(format, args...)}
}
