### `protocol.go`

```go
package broll

import (
	"bytes"
	"compress/flate"
	"encoding/binary"
	"hash/crc32"
	"io"
	"math"
)

const (
	headerSize = 2 + 1 + 8 + 8 + 4

	magic0 = 0xB7
	magic1 = 0x01

	flagCompressed = 1 << 0
	flagNested     = 1 << 1
)

var castagnoli = crc32.MakeTable(crc32.Castagnoli)

type Config struct {
	MaxFramePayload uint64
	MaxDecompressed uint64
	MaxBufferBytes  int
	MaxDepth        int
	MaxWork         uint64
}

func DefaultConfig() Config {
	return Config{
		MaxFramePayload: 8 << 20,
		MaxDecompressed: 64 << 20,
		MaxBufferBytes:  16 << 20,
		MaxDepth:        32,
		MaxWork:         1 << 32,
	}
}

func (c Config) withDefaults() Config {
	d := DefaultConfig()
	if c.MaxFramePayload == 0 {
		c.MaxFramePayload = d.MaxFramePayload
	}
	if c.MaxDecompressed == 0 {
		c.MaxDecompressed = d.MaxDecompressed
	}
	if c.MaxBufferBytes == 0 {
		c.MaxBufferBytes = d.MaxBufferBytes
	}
	if c.MaxDepth == 0 {
		c.MaxDepth = d.MaxDepth
	}
	if c.MaxWork == 0 {
		c.MaxWork = d.MaxWork
	}
	return c
}

type Frame struct {
	Flags  uint8
	Data   []byte
	Nested []Frame
	Offset int64
}

func (f Frame) Compressed() bool { return f.Flags&flagCompressed != 0 }
func (f Frame) NestedFlag() bool { return f.Flags&flagNested != 0 }

func SafeAdd(a, b uint64) (uint64, bool) {
	if a > math.MaxUint64-b {
		return 0, false
	}
	return a + b, true
}

func inflate(src []byte, declared, limit uint64) ([]byte, error) {
	if declared > limit {
		return nil, perr(KindDecompressionBomb, 0, "declared %d > limit %d", declared, limit)
	}
	fr := flate.NewReader(bytes.NewReader(src))
	defer fr.Close()

	out := make([]byte, declared)
	if _, err := io.ReadFull(fr, out); err != nil {
		if err == io.EOF || err == io.ErrUnexpectedEOF {
			return nil, perr(KindDecompressionCorrupt, 0, "stream ended before %d bytes", declared)
		}
		return nil, perr(KindDecompressionCorrupt, 0, "%v", err)
	}
	var extra [1]byte
	if n, err := fr.Read(extra[:]); n > 0 {
		return nil, perr(KindDecompressionBomb, 0, "stream produced more than %d bytes", declared)
	} else if err != nil && err != io.EOF {
		return nil, perr(KindDecompressionCorrupt, 0, "%v", err)
	}
	return out, nil
}

func parseFrameAt(cfg Config, b []byte, depth int, absOff int64) (Frame, int, error) {
	if len(b) < headerSize {
		return Frame{}, 0, perr(KindIncomplete, absOff, "need %d header bytes, have %d", headerSize, len(b))
	}
	if b[0] != magic0 || b[1] != magic1 {
		return Frame{}, 0, perr(KindMalformed, absOff, "bad magic %02x%02x", b[0], b[1])
	}
	flags := b[2]
	onwire := binary.BigEndian.Uint64(b[3:11])
	logical := binary.BigEndian.Uint64(b[11:19])
	crc := binary.BigEndian.Uint32(b[19:23])

	if onwire > cfg.MaxFramePayload {
		return Frame{}, 0, perr(KindFrameTooLarge, absOff, "payload %d > max %d", onwire, cfg.MaxFramePayload)
	}
	total, ok := SafeAdd(headerSize, onwire)
	if !ok || total > math.MaxInt {
		return Frame{}, 0, perr(KindIntegerOverflow, absOff, "header+payload overflow (%d+%d)", headerSize, onwire)
	}
	if uint64(len(b)) < total {
		return Frame{}, 0, perr(KindIncomplete, absOff, "need %d bytes, have %d", total, len(b))
	}
	payload := b[headerSize:total]
	if got := crc32.Checksum(payload, castagnoli); got != crc {
		return Frame{}, int(total), perr(KindChecksum, absOff, "have %08x want %08x", got, crc)
	}

	var data []byte
	if flags&flagCompressed != 0 {
		if logical > cfg.MaxDecompressed {
			return Frame{}, int(total), perr(KindDecompressionBomb, absOff, "declared %d > max %d", logical, cfg.MaxDecompressed)
		}
		d, err := inflate(payload, logical, cfg.MaxDecompressed)
		if err != nil {
			if pe, ok := err.(*ParseError); ok {
				pe.Offset = absOff
				return Frame{}, int(total), pe
			}
			return Frame{}, int(total), err
		}
		data = d
	} else {
		if logical != onwire {
			return Frame{}, int(total), perr(KindMalformed, absOff, "uncompressed logical %d != onwire %d", logical, onwire)
		}
		data = append([]byte(nil), payload...)
	}

	f := Frame{Flags: flags, Data: data, Offset: absOff}
	if flags&flagNested != 0 {
		if depth+1 > cfg.MaxDepth {
			return Frame{}, int(total), perr(KindDepthExceeded, absOff, "depth %d > max %d", depth+1, cfg.MaxDepth)
		}
		children, err := parseNested(cfg, data, depth+1, absOff+headerSize)
		if err != nil {
			return Frame{}, int(total), err
		}
		f.Nested = children
	}
	return f, int(total), nil
}

func parseNested(cfg Config, data []byte, depth int, absOff int64) ([]Frame, error) {
	var out []Frame
	pos := 0
	for pos < len(data) {
		f, n, err := parseFrameAt(cfg, data[pos:], depth, absOff+int64(pos))
		if err != nil {
			if pe, ok := err.(*ParseError); ok && pe.Kind == KindIncomplete {
				return nil, perr(KindMalformed, pe.Offset, "truncated nested frame")
			}
			return nil, err
		}
		out = append(out, f)
		pos += n
	}
	return out, nil
}
