### `encode.go`

```go
package broll

import (
	"bytes"
	"compress/flate"
	"encoding/binary"
	"hash/crc32"
)

func Encode(data []byte, compressed, nested bool) []byte {
	onwire := data
	flags := uint8(0)
	if compressed {
		flags |= flagCompressed
		var buf bytes.Buffer
		zw, _ := flate.NewWriter(&buf, flate.BestSpeed)
		_, _ = zw.Write(data)
		_ = zw.Close()
		onwire = buf.Bytes()
	}
	if nested {
		flags |= flagNested
	}
	out := make([]byte, headerSize+len(onwire))
	out[0], out[1] = magic0, magic1
	out[2] = flags
	binary.BigEndian.PutUint64(out[3:11], uint64(len(onwire)))
	binary.BigEndian.PutUint64(out[11:19], uint64(len(data)))
	binary.BigEndian.PutUint32(out[19:23], crc32.Checksum(onwire, castagnoli))
	copy(out[headerSize:], onwire)
	return out
}

func EncodeContainer(children ...[]byte) []byte {
	var payload []byte
	for _, c := range children {
		payload = append(payload, c...)
	}
	return Encode(payload, false, true)
}

func EncodeCompressedContainer(children ...[]byte) []byte {
	var payload []byte
	for _, c := range children {
		payload = append(payload, c...)
	}
	return Encode(payload, true, true)
}
