### `parser.go`

```go
package broll

import (
	"errors"
	"time"
)

type Parser struct {
	cfg Config

	buf          []byte
	base         int64
	cursor       int
	commitCursor int

	committed []Frame
	pending   []Frame
	errs      []*ParseError

	work        uint64
	deadline    time.Time
	budgetFired bool
}

func New(cfg Config) *Parser {
	return &Parser{cfg: cfg.withDefaults()}
}

func (p *Parser) SetDeadline(t time.Time) { p.deadline = t }

func (p *Parser) Write(b []byte) (int, error) {
	p.buf = append(p.buf, b...)
	p.Process()
	return len(b), nil
}

func (p *Parser) Process() {
	for {
		if !p.deadline.IsZero() && time.Now().After(p.deadline) {
			p.record(KindCPUBudget, p.base+int64(p.cursor), "wall-clock deadline exceeded")
			return
		}
		if p.work > p.cfg.MaxWork {
			p.record(KindCPUBudget, p.base+int64(p.cursor), "work %d > max %d", p.work, p.cfg.MaxWork)
			p.cursor = len(p.buf)
			return
		}

		i := findMagic(p.buf, p.cursor)
		if i < 0 {
			p.work += uint64(len(p.buf) - p.cursor)
			keep := 0
			if len(p.buf) > p.cursor && p.buf[len(p.buf)-1] == magic0 {
				keep = 1
			}
			p.cursor = len(p.buf) - keep
			return
		}
		if i > p.cursor {
			p.record(KindMalformed, p.base+int64(p.cursor), "dropped %d bytes before magic", i-p.cursor)
			p.work += uint64(i - p.cursor)
			p.cursor = i
		}

		f, n, err := parseFrameAt(p.cfg, p.buf[p.cursor:], 0, p.base+int64(p.cursor))
		if n > 0 {
			p.work += uint64(n)
		}
		if err != nil {
			if errors.Is(err, ErrIncomplete) {
				if len(p.buf)-p.commitCursor > p.cfg.MaxBufferBytes {
					p.record(KindBufferBudget, p.base+int64(p.cursor),
						"retained %d > max %d", len(p.buf)-p.commitCursor, p.cfg.MaxBufferBytes)
					p.cursor++
					if p.cursor > len(p.buf) {
						p.cursor = len(p.buf)
					}
					continue
				}
				return
			}
			p.recordErr(err)
			skip := n
			if skip <= 0 {
				skip = 1
			}
			p.cursor += skip
			if p.cursor > len(p.buf) {
				p.cursor = len(p.buf)
			}
			continue
		}

		p.pending = append(p.pending, f)
		p.cursor += n
	}
}

func (p *Parser) Commit() {
	if len(p.pending) == 0 {
		p.commitCursor = p.cursor
		p.trim()
		return
	}
	p.committed = append(p.committed, p.pending...)
	p.pending = nil
	p.commitCursor = p.cursor
	p.trim()
}

func (p *Parser) trim() {
	if p.commitCursor <= 0 {
		return
	}
	n := copy(p.buf, p.buf[p.commitCursor:])
	p.buf = p.buf[:n]
	p.base += int64(p.commitCursor)
	p.cursor -= p.commitCursor
	p.commitCursor = 0
}

func (p *Parser) Rollback() {
	p.pending = nil
	p.cursor = p.commitCursor
}

func (p *Parser) DiscardUncommitted() {
	p.pending = nil
	p.cursor = len(p.buf)
	p.trim()
	p.Process()
}

func (p *Parser) Frames() []Frame            { return p.committed }
func (p *Parser) Pending() []Frame           { return p.pending }
func (p *Parser) Errors() []*ParseError      { return p.errs }
func (p *Parser) LastCommittedOffset() int64 { return p.base + int64(p.commitCursor) }

func (p *Parser) recordErr(err error) {
	var pe *ParseError
	if errors.As(err, &pe) {
		p.errs = append(p.errs, pe)
		return
	}
	p.errs = append(p.errs, perr(KindMalformed, p.base+int64(p.cursor), "%v", err))
}

func (p *Parser) record(k Kind, off int64, format string, args ...any) {
	p.errs = append(p.errs, perr(k, off, format, args...))
}

func findMagic(b []byte, from int) int {
	for i := from; i+1 < len(b); i++ {
		if b[i] == magic0 && b[i+1] == magic1 {
			return i
		}
	}
	return -1
}
```

> Note: `budgetFired` is retained as a hook; the CPU budget is enforced via `work` and `deadline`.

### API summary

- `New(Config)` → parser with strict budgets (zero → safe defaults).
- `Write([]byte)` → feed arbitrary fragments, never errors on the write itself.
- `Process()` → run the state machine to quiescence.
- `Commit()` → promote pending frames, release their bytes; `Rollback()` → rewind to last committed frame; `DiscardUncommitted()` → drop pending bytes without rewinding.
- `Frames()`, `Pending()`, `Errors()`, `LastCommittedOffset()`.
- `errors.Is(err, ErrChecksumMismatch | ErrIntegerOverflow | ErrDecompressionBomb | ...)`.

