```go
package broll

import (
	"bytes"
	"encoding/binary"
	"errors"
	"hash/crc32"
	"math"
	"testing"
)

func rawFrame(flags uint8, onwire, logical uint64, crc uint32, payload []byte) []byte {
	b := make([]byte, headerSize+len(payload))
	b[0], b[1], b[2] = magic0, magic1, flags
	binary.BigEndian.PutUint64(b[3:11], onwire)
	binary.BigEndian.PutUint64(b[11:19], logical)
	binary.BigEndian.PutUint32(b[19:23], crc)
	copy(b[headerSize:], payload)
	return b
}

func mustCommit(t *testing.T, p *Parser) []Frame {
	t.Helper()
	p.Process()
	p.Commit()
	return p.Frames()
}

func TestFragmentedByteByByte(t *testing.T) {
	want := []byte("hello streaming world")
	wire := Encode(want, false, false)
	p := New(Config{})

	for i := 0; i < len(wire); i++ {
		if _, err := p.Write(wire[i : i+1]); err != nil {
			t.Fatalf("write: %v", err)
		}
		if i < len(wire)-1 && len(p.Pending()) != 0 {
			t.Fatalf("frame committed early at byte %d", i)
		}
	}
	frames := mustCommit(t, p)
	if len(frames) != 1 {
		t.Fatalf("got %d frames, want 1; errs=%v", len(frames), p.Errors())
	}
	if !bytes.Equal(frames[0].Data, want) {
		t.Fatalf("payload mismatch: %q", frames[0].Data)
	}
	if len(p.Errors()) != 0 {
		t.Fatalf("unexpected errors: %v", p.Errors())
	}
}

func TestCompressedRoundTrip(t *testing.T) {
	payload := bytes.Repeat([]byte("abc123"), 5000)
	wire := Encode(payload, true, false)
	p := New(Config{})
	p.Write(wire)
	frames := mustCommit(t, p)
	if len(frames) != 1 {
		t.Fatalf("got %d frames; errs=%v", len(frames), p.Errors())
	}
	if !bytes.Equal(frames[0].Data, payload) {
		t.Fatal("decompressed payload mismatch")
	}
	if !frames[0].Compressed() {
		t.Fatal("compressed flag lost")
	}
}

func TestNestedContainer(t *testing.T) {
	inner1 := Encode([]byte("child-1"), false, false)
	inner2 := Encode([]byte("child-2"), true, false)
	wire := EncodeContainer(inner1, inner2)
	p := New(Config{})
	p.Write(wire)
	frames := mustCommit(t, p)
	if len(frames) != 1 || !frames[0].NestedFlag() {
		t.Fatalf("expected one nested frame; errs=%v", p.Errors())
	}
	if len(frames[0].Nested) != 2 {
		t.Fatalf("got %d children, want 2", len(frames[0].Nested))
	}
	if string(frames[0].Nested[0].Data) != "child-1" || string(frames[0].Nested[1].Data) != "child-2" {
		t.Fatalf("children wrong: %q %q", frames[0].Nested[0].Data, frames[0].Nested[1].Data)
	}
}

func TestChecksumFailureDoesNotCorruptFollowing(t *testing.T) {
	bad := Encode([]byte("corrupt me"), false, false)
	bad[headerSize+3] ^= 0xFF
	good := Encode([]byte("valid after corruption"), false, false)

	p := New(Config{})
	p.Write(append(append([]byte{}, bad...), good...))
	frames := mustCommit(t, p)

	if len(frames) != 1 {
		t.Fatalf("got %d committed frames, want 1; errs=%v", len(frames), p.Errors())
	}
	if string(frames[0].Data) != "valid after corruption" {
		t.Fatalf("wrong survivor: %q", frames[0].Data)
	}
	if len(p.Errors()) != 1 || !errors.Is(p.Errors()[0], ErrChecksumMismatch) {
		t.Fatalf("want one checksum error, got %v", p.Errors())
	}
}

func TestIntegerOverflow(t *testing.T) {
	wire := make([]byte, headerSize)
	wire[0], wire[1], wire[2] = magic0, magic1, 0
	binary.BigEndian.PutUint64(wire[3:11], math.MaxUint64)
	p := New(Config{MaxFramePayload: math.MaxUint64})
	p.Write(wire)
	if len(p.Errors()) != 1 || !errors.Is(p.Errors()[0], ErrIntegerOverflow) {
		t.Fatalf("want integer overflow, got %v", p.Errors())
	}
}

func TestDecompressionBombDeclared(t *testing.T) {
	wire := Encode(bytes.Repeat([]byte("x"), 1000), true, false)
	p := New(Config{MaxDecompressed: 16})
	p.Write(wire)
	if len(p.Errors()) != 1 || !errors.Is(p.Errors()[0], ErrDecompressionBomb) {
		t.Fatalf("want bomb, got %v", p.Errors())
	}
	if len(p.Frames()) != 0 {
		t.Fatal("bomb frame was committed")
	}
}

func TestDecompressionBombActual(t *testing.T) {
	wire := Encode(bytes.Repeat([]byte("y"), 5000), true, false)
	binary.BigEndian.PutUint64(wire[11:19], 10)
	p := New(Config{})
	p.Write(wire)
	if len(p.Errors()) != 1 || !errors.Is(p.Errors()[0], ErrDecompressionBomb) {
		t.Fatalf("want actual bomb, got %v", p.Errors())
	}
}

func TestDecompressionCorruptNotBomb(t *testing.T) {
	wire := Encode(bytes.Repeat([]byte("z"), 1000), true, false)
	binary.BigEndian.PutUint64(wire[11:19], 5000)
	p := New(Config{})
	p.Write(wire)
	if len(p.Errors()) != 1 || !errors.Is(p.Errors()[0], ErrDecompressionCorrupt) {
		t.Fatalf("want corrupt, got %v", p.Errors())
	}
	if errors.Is(p.Errors()[0], ErrDecompressionBomb) {
		t.Fatal("corruption must not be reported as a bomb")
	}
