func TestRollbackToLastCommitted(t *testing.T) {
	p := New(Config{})
	p.Write(Encode([]byte("one"), false, false))
	p.Write(Encode([]byte("two"), false, false))
	p.Process()
	p.Commit()
	if len(p.Frames()) != 2 {
		t.Fatalf("want 2 committed, got %d", len(p.Frames()))
	}
	committedOffset := p.LastCommittedOffset()

	p.Write(Encode([]byte("three"), false, false))
	if len(p.Pending()) != 1 {
		t.Fatalf("want 1 pending, got %d", len(p.Pending()))
	}

	p.Rollback()
	if len(p.Pending()) != 0 {
		t.Fatalf("rollback left %d pending", len(p.Pending()))
	}
	if len(p.Frames()) != 2 {
		t.Fatalf("rollback changed committed count: %d", len(p.Frames()))
	}
	if p.LastCommittedOffset() != committedOffset {
		t.Fatalf("offset moved: %d != %d", p.LastCommittedOffset(), committedOffset)
	}

	p.Process()
	if len(p.Pending()) != 1 || string(p.Pending()[0].Data) != "three" {
		t.Fatalf("retry did not recover frame: %v", p.Pending())
	}
	p.Commit()
	if len(p.Frames()) != 3 {
		t.Fatalf("want 3 committed after retry, got %d", len(p.Frames()))
	}
}

func TestBufferBudget(t *testing.T) {
	wire := Encode(bytes.Repeat([]byte("b"), 4096), false, false)
	p := New(Config{MaxFramePayload: 1 << 20, MaxBufferBytes: 128})
	p.Write(wire[:200])
	if len(p.Errors()) == 0 || !errors.Is(p.Errors()[0], ErrBufferBudget) {
		t.Fatalf("want buffer budget error, got %v", p.Errors())
	}
}

func TestDepthExceeded(t *testing.T) {
	inner := Encode([]byte("leaf"), false, false)
	wire := inner
	for i := 0; i < 5; i++ {
		wire = EncodeContainer(wire)
	}
	p := New(Config{MaxDepth: 3})
	p.Write(wire)
	found := false
	for _, e := range p.Errors() {
